from pathlib import Path
import sys
import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles, RisingEdge, Timer

sys.path.append(str(Path(__file__).parent.parent))
from cocotb_utils import CLK_PERIOD_NS, Runner, setup_runner

NOP = 0x00000013


def load_hex_file(filepath):
    """Parse hex file generated by objcopy -O verilog."""
    raw_bytes = []
    with open(filepath, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("//") or line.startswith("@"):
                continue
            parts = line.split()
            for part in parts:
                raw_bytes.append(int(part, 16))
    words = []
    for i in range(0, len(raw_bytes), 4):
        if i + 3 < len(raw_bytes):
            b0, b1, b2, b3 = raw_bytes[i : i + 4]
            words.append((b3 << 24) | (b2 << 16) | (b1 << 8) | b0)
    return words


def fill_mem(dut, words: list[int]):
    """Fill IMem with program words, padding remaining space with NOPs."""
    imem_size = len(dut.u_ifu.IMem.imem.mem)
    for i in range(imem_size):
        dut.u_ifu.IMem.imem.mem[i].value = NOP
    for i, word in enumerate(words):
        dut.u_ifu.IMem.imem.mem[i].value = word


def read_dmem(dut, byte_addr: int) -> int:
    """Read DMEM word by byte address and cast to 32-bit signed int."""
    val = int(dut.u_dmem.dmem.mem[byte_addr // 4].value)
    if val & 0x80000000:
        val -= 0x100000000
    return val


async def setup_dut(dut, start_pc: int = 0):
    """Initialize clock and reset pulse for DUT setup."""
    clock = Clock(dut.clk, CLK_PERIOD_NS, unit="ns")
    cocotb.start_soon(clock.start())
    dut.rst.value = 1
    dut.start.value = 0
    dut.program_address.value = start_pc

    await ClockCycles(dut.clk, 2)
    await Timer(1, unit="step")
    dut.rst.value = 0
    dut.start.value = 1
    await RisingEdge(dut.clk)
    await Timer(1, unit="step")
    dut.start.value = 0


@cocotb.test()
async def t_core_c_binary_search_test(dut):
    """Run C binary search test and verify target index results."""
    TEST_DIR = Path(__file__).parent.parent
    hex_path = TEST_DIR / "build" / "binary_search" / "test.hex"

    fill_mem(dut, load_hex_file(hex_path))
    await setup_dut(dut, start_pc=0)

    max_cycles = 2000
    done = False

    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if read_dmem(dut, byte_addr=0x2000) == 1:
            dut._log.info(f"Completion flag detected at cycle {cycle}.")
            done = True
            break

    assert done, "Binary search test execution timed out!"

    idx1 = read_dmem(dut, byte_addr=0x1000)
    idx2 = read_dmem(dut, byte_addr=0x1004)

    dut._log.info(f"Search for 23 returned index: {idx1} (Expected: 5)")
    dut._log.info(f"Search for 99 returned index: {idx2} (Expected: -1)")

    assert idx1 == 5, f"Search for existing element failed! Expected 5, got {idx1}"
    assert idx2 == -1, f"Search for non-existent element failed! Expected -1, got {idx2}"
    dut._log.info("Binary search test passed successfully!")


class TestCore_SV:
    runner: Runner
    hdl_top: str

    @classmethod
    def setup_class(cls):
        COREX_ROOT = Path(__file__).parent.parent.parent
        hdl_dir = COREX_ROOT / "hdl_sv" / "core"
        sources = [
            hdl_dir / "control_unit.sv",
            hdl_dir / "ibus_if.sv",
            hdl_dir / "dbus_if.sv",
            hdl_dir / "imem.sv",
            hdl_dir / "dmem.sv",
            hdl_dir / "reg_file.sv",
            hdl_dir / "pipeline_reg.sv",
            hdl_dir / "decoder.sv",
            hdl_dir / "ALU.sv",
            hdl_dir / "execute.sv",
            hdl_dir / "ifu.sv",
            hdl_dir / "core.sv",
        ]
        cls.hdl_top = "CoreTop"
        cls.runner = setup_runner(sources=sources, hdl_toplevel=cls.hdl_top)

    def test_c_binary_search(self):
        self.runner.test(
            hdl_toplevel=self.hdl_top,
            test_module=f"testcases.{Path(__file__).stem}",
            testcase="t_core_c_binary_search_test",
        )